CREATE TABLE "menus" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"tenant_id" uuid NOT NULL REFERENCES "tenants"("id"),"name" text NOT NULL,"description" text DEFAULT '' NOT NULL,"status" text DEFAULT 'DRAFT' NOT NULL,"revision" integer DEFAULT 1 NOT NULL,"published_at" timestamptz,"archived_at" timestamptz,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,CONSTRAINT "menus_status_check" CHECK (status IN ('DRAFT','PUBLISHED','ARCHIVED')),CONSTRAINT "menus_revision_check" CHECK (revision>0),CONSTRAINT "menus_id_tenant_unique" UNIQUE("id","tenant_id"));
CREATE UNIQUE INDEX "menus_tenant_name_draft_unique" ON "menus"("tenant_id","name") WHERE status='DRAFT';
CREATE INDEX "menus_tenant_status_idx" ON "menus"("tenant_id","status");

CREATE TABLE "menu_categories" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"tenant_id" uuid NOT NULL REFERENCES "tenants"("id"),"menu_id" uuid NOT NULL,"name" text NOT NULL,"description" text DEFAULT '' NOT NULL,"display_order" integer DEFAULT 0 NOT NULL,"active" boolean DEFAULT true NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,CONSTRAINT "menu_categories_menu_tenant_fk" FOREIGN KEY("menu_id","tenant_id") REFERENCES "menus"("id","tenant_id"),CONSTRAINT "menu_categories_id_tenant_unique" UNIQUE("id","tenant_id"),CONSTRAINT "menu_categories_tenant_menu_name_unique" UNIQUE("tenant_id","menu_id","name"));
CREATE INDEX "menu_categories_menu_idx" ON "menu_categories"("tenant_id","menu_id");

CREATE TABLE "menu_products" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"tenant_id" uuid NOT NULL REFERENCES "tenants"("id"),"menu_id" uuid NOT NULL,"category_id" uuid NOT NULL,"name" text NOT NULL,"description" text DEFAULT '' NOT NULL,"sku" text,"type" text NOT NULL,"base_price_minor" integer DEFAULT 0 NOT NULL,"active" boolean DEFAULT true NOT NULL,"displayed" boolean DEFAULT true NOT NULL,"display_order" integer DEFAULT 0 NOT NULL,"maximum_quantity" integer DEFAULT 20 NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,CONSTRAINT "menu_products_menu_tenant_fk" FOREIGN KEY("menu_id","tenant_id") REFERENCES "menus"("id","tenant_id"),CONSTRAINT "menu_products_category_tenant_fk" FOREIGN KEY("category_id","tenant_id") REFERENCES "menu_categories"("id","tenant_id"),CONSTRAINT "menu_products_id_tenant_unique" UNIQUE("id","tenant_id"),CONSTRAINT "menu_products_id_tenant_menu_unique" UNIQUE("id","tenant_id","menu_id"),CONSTRAINT "menu_products_type_check" CHECK(type IN ('FOOD','DRINK','MEAL','SIDE','PROTEIN','EXTRA')),CONSTRAINT "menu_products_price_check" CHECK(base_price_minor>=0),CONSTRAINT "menu_products_quantity_check" CHECK(maximum_quantity BETWEEN 1 AND 100));
CREATE UNIQUE INDEX "menu_products_tenant_sku_unique" ON "menu_products"("tenant_id","sku") WHERE sku IS NOT NULL;
CREATE INDEX "menu_products_menu_idx" ON "menu_products"("tenant_id","menu_id");

CREATE TABLE "product_configurations" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"tenant_id" uuid NOT NULL REFERENCES "tenants"("id"),"menu_id" uuid NOT NULL,"product_id" uuid NOT NULL,"name" text NOT NULL,"kind" text NOT NULL,"active" boolean DEFAULT true NOT NULL,"display_order" integer DEFAULT 0 NOT NULL,"revision" integer DEFAULT 1 NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,CONSTRAINT "product_configurations_menu_tenant_fk" FOREIGN KEY("menu_id","tenant_id") REFERENCES "menus"("id","tenant_id"),CONSTRAINT "product_configurations_product_tenant_fk" FOREIGN KEY("product_id","tenant_id","menu_id") REFERENCES "menu_products"("id","tenant_id","menu_id"),CONSTRAINT "product_configurations_id_tenant_unique" UNIQUE("id","tenant_id"),CONSTRAINT "product_configurations_product_name_unique" UNIQUE("tenant_id","product_id","name"),CONSTRAINT "product_configurations_kind_check" CHECK(kind IN ('SIMPLE','FULL_PACKAGE','BUILD_YOUR_OWN')),CONSTRAINT "product_configurations_revision_check" CHECK(revision>0));
CREATE INDEX "product_configurations_product_idx" ON "product_configurations"("tenant_id","product_id");

CREATE TABLE "component_groups" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"tenant_id" uuid NOT NULL REFERENCES "tenants"("id"),"menu_id" uuid NOT NULL,"configuration_id" uuid NOT NULL,"name" text NOT NULL,"minimum_selections" integer DEFAULT 0 NOT NULL,"maximum_selections" integer DEFAULT 1 NOT NULL,"required" boolean DEFAULT false NOT NULL,"display_order" integer DEFAULT 0 NOT NULL,"pricing_behavior" text DEFAULT 'ADDITIVE' NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,CONSTRAINT "component_groups_configuration_tenant_fk" FOREIGN KEY("configuration_id","tenant_id") REFERENCES "product_configurations"("id","tenant_id"),CONSTRAINT "component_groups_menu_tenant_fk" FOREIGN KEY("menu_id","tenant_id") REFERENCES "menus"("id","tenant_id"),CONSTRAINT "component_groups_id_tenant_unique" UNIQUE("id","tenant_id"),CONSTRAINT "component_groups_configuration_name_unique" UNIQUE("tenant_id","configuration_id","name"),CONSTRAINT "component_groups_selection_check" CHECK(minimum_selections>=0 AND maximum_selections>=minimum_selections AND maximum_selections<=100),CONSTRAINT "component_groups_required_check" CHECK(NOT required OR minimum_selections>0),CONSTRAINT "component_groups_pricing_check" CHECK(pricing_behavior IN ('INCLUDED','ADDITIVE')));
CREATE INDEX "component_groups_configuration_idx" ON "component_groups"("tenant_id","configuration_id");

CREATE TABLE "component_options" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"tenant_id" uuid NOT NULL REFERENCES "tenants"("id"),"menu_id" uuid NOT NULL,"group_id" uuid NOT NULL,"option_product_id" uuid,"name" text NOT NULL,"type" text NOT NULL,"price_adjustment_minor" integer DEFAULT 0 NOT NULL,"minimum_quantity" integer DEFAULT 1 NOT NULL,"maximum_quantity" integer DEFAULT 1 NOT NULL,"active" boolean DEFAULT true NOT NULL,"display_order" integer DEFAULT 0 NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,CONSTRAINT "component_options_group_tenant_fk" FOREIGN KEY("group_id","tenant_id") REFERENCES "component_groups"("id","tenant_id"),CONSTRAINT "component_options_menu_tenant_fk" FOREIGN KEY("menu_id","tenant_id") REFERENCES "menus"("id","tenant_id"),CONSTRAINT "component_options_product_tenant_fk" FOREIGN KEY("option_product_id","tenant_id","menu_id") REFERENCES "menu_products"("id","tenant_id","menu_id"),CONSTRAINT "component_options_id_tenant_unique" UNIQUE("id","tenant_id"),CONSTRAINT "component_options_group_name_unique" UNIQUE("tenant_id","group_id","name"),CONSTRAINT "component_options_type_check" CHECK(type IN ('INCLUDED','PAID_ADDON','SUBSTITUTION','REMOVABLE','REQUIRED','OPTIONAL')),CONSTRAINT "component_options_quantity_check" CHECK(minimum_quantity>=1 AND maximum_quantity>=minimum_quantity AND maximum_quantity<=100));
CREATE INDEX "component_options_group_idx" ON "component_options"("tenant_id","group_id");

CREATE TABLE "option_substitutions" ("tenant_id" uuid NOT NULL REFERENCES "tenants"("id"),"option_id" uuid NOT NULL,"substitute_option_id" uuid NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,PRIMARY KEY("option_id","substitute_option_id"),CONSTRAINT "option_substitutions_option_tenant_fk" FOREIGN KEY("option_id","tenant_id") REFERENCES "component_options"("id","tenant_id") ON DELETE CASCADE,CONSTRAINT "option_substitutions_substitute_tenant_fk" FOREIGN KEY("substitute_option_id","tenant_id") REFERENCES "component_options"("id","tenant_id") ON DELETE CASCADE,CONSTRAINT "option_substitutions_not_self_check" CHECK(option_id<>substitute_option_id));

CREATE TABLE "ingredients" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"tenant_id" uuid NOT NULL REFERENCES "tenants"("id"),"name" text NOT NULL,"default_unit" text NOT NULL,"active" boolean DEFAULT true NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,CONSTRAINT "ingredients_id_tenant_unique" UNIQUE("id","tenant_id"),CONSTRAINT "ingredients_tenant_name_unique" UNIQUE("tenant_id","name"),CONSTRAINT "ingredients_unit_check" CHECK(default_unit IN ('GRAM','KILOGRAM','MILLILITRE','LITRE','UNIT','PORTION')));

CREATE TABLE "product_ingredient_dependencies" ("tenant_id" uuid NOT NULL REFERENCES "tenants"("id"),"product_id" uuid NOT NULL,"ingredient_id" uuid NOT NULL,"dependency_type" text NOT NULL,"quantity" integer NOT NULL,"unit" text NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,PRIMARY KEY("product_id","ingredient_id"),CONSTRAINT "product_ingredient_product_tenant_fk" FOREIGN KEY("product_id","tenant_id") REFERENCES "menu_products"("id","tenant_id") ON DELETE CASCADE,CONSTRAINT "product_ingredient_ingredient_tenant_fk" FOREIGN KEY("ingredient_id","tenant_id") REFERENCES "ingredients"("id","tenant_id"),CONSTRAINT "product_ingredient_type_check" CHECK(dependency_type IN ('REQUIRED','OPTIONAL')),CONSTRAINT "product_ingredient_quantity_check" CHECK(quantity>0),CONSTRAINT "product_ingredient_unit_check" CHECK(unit IN ('GRAM','KILOGRAM','MILLILITRE','LITRE','UNIT','PORTION')));

CREATE TABLE "ingredient_availability" ("tenant_id" uuid NOT NULL REFERENCES "tenants"("id"),"location_id" uuid NOT NULL,"ingredient_id" uuid NOT NULL,"status" text NOT NULL,"version" integer DEFAULT 1 NOT NULL,"changed_by" uuid NOT NULL,"reason" text NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,PRIMARY KEY("location_id","ingredient_id"),CONSTRAINT "ingredient_availability_location_tenant_fk" FOREIGN KEY("location_id","tenant_id") REFERENCES "locations"("id","tenant_id"),CONSTRAINT "ingredient_availability_ingredient_tenant_fk" FOREIGN KEY("ingredient_id","tenant_id") REFERENCES "ingredients"("id","tenant_id"),CONSTRAINT "ingredient_availability_actor_tenant_fk" FOREIGN KEY("changed_by","tenant_id") REFERENCES "users"("id","tenant_id"),CONSTRAINT "ingredient_availability_status_check" CHECK(status IN ('AVAILABLE','UNAVAILABLE')),CONSTRAINT "ingredient_availability_version_check" CHECK(version>0));
CREATE TABLE "product_availability" ("tenant_id" uuid NOT NULL REFERENCES "tenants"("id"),"location_id" uuid NOT NULL,"product_id" uuid NOT NULL,"status" text NOT NULL,"version" integer DEFAULT 1 NOT NULL,"changed_by" uuid NOT NULL,"reason" text NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL,PRIMARY KEY("location_id","product_id"),CONSTRAINT "product_availability_location_tenant_fk" FOREIGN KEY("location_id","tenant_id") REFERENCES "locations"("id","tenant_id"),CONSTRAINT "product_availability_product_tenant_fk" FOREIGN KEY("product_id","tenant_id") REFERENCES "menu_products"("id","tenant_id"),CONSTRAINT "product_availability_actor_tenant_fk" FOREIGN KEY("changed_by","tenant_id") REFERENCES "users"("id","tenant_id"),CONSTRAINT "product_availability_status_check" CHECK(status IN ('AVAILABLE','UNAVAILABLE')),CONSTRAINT "product_availability_version_check" CHECK(version>0));

CREATE TABLE "menu_publications" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"tenant_id" uuid NOT NULL REFERENCES "tenants"("id"),"menu_id" uuid NOT NULL,"version" integer NOT NULL,"snapshot" jsonb NOT NULL,"snapshot_hash" text NOT NULL,"published_by" uuid NOT NULL,"published_at" timestamptz DEFAULT now() NOT NULL,CONSTRAINT "menu_publications_menu_tenant_fk" FOREIGN KEY("menu_id","tenant_id") REFERENCES "menus"("id","tenant_id"),CONSTRAINT "menu_publications_actor_tenant_fk" FOREIGN KEY("published_by","tenant_id") REFERENCES "users"("id","tenant_id"),CONSTRAINT "menu_publications_id_tenant_unique" UNIQUE("id","tenant_id"),CONSTRAINT "menu_publications_menu_version_unique" UNIQUE("tenant_id","menu_id","version"),CONSTRAINT "menu_publications_hash_unique" UNIQUE("tenant_id","snapshot_hash"));

CREATE FUNCTION reject_menu_publication_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND rolsuper) THEN RAISE EXCEPTION 'menu publication snapshots are immutable'; END IF; RETURN OLD; END $$;
CREATE TRIGGER menu_publications_immutable BEFORE UPDATE OR DELETE ON menu_publications FOR EACH ROW EXECUTE FUNCTION reject_menu_publication_mutation();

INSERT INTO role_permissions(tenant_id,role_id,permission_code)
SELECT r.tenant_id,r.id,p.code FROM roles r CROSS JOIN permissions p WHERE (r.code='ADMIN' AND p.code IN ('menu:view','menu:create','menu:update','menu:publish','pricing:view','pricing:update')) OR (r.code='MANAGER' AND p.code IN ('menu:view','menu:update','pricing:view')) OR (r.code IN ('FOH','KITCHEN','PACKING') AND p.code='menu:view') OR (r.code='FOH' AND p.code='pricing:view') ON CONFLICT DO NOTHING;

CREATE FUNCTION provision_menu_permissions_for_tenant() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
  INSERT INTO role_permissions(tenant_id,role_id,permission_code) SELECT r.tenant_id,r.id,p.code FROM roles r CROSS JOIN permissions p WHERE r.tenant_id=NEW.id AND ((r.code='ADMIN' AND p.code IN ('menu:view','menu:create','menu:update','menu:publish','pricing:view','pricing:update')) OR (r.code='MANAGER' AND p.code IN ('menu:view','menu:update','pricing:view')) OR (r.code IN ('FOH','KITCHEN','PACKING') AND p.code='menu:view') OR (r.code='FOH' AND p.code='pricing:view')) ON CONFLICT DO NOTHING;
  RETURN NEW;
END $$;
CREATE TRIGGER tenants_z_menu_permissions AFTER INSERT ON tenants FOR EACH ROW EXECUTE FUNCTION provision_menu_permissions_for_tenant();

DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='restaurant_os_app') THEN
  GRANT SELECT,INSERT,UPDATE ON menus,menu_categories,menu_products,product_configurations,component_groups,component_options,option_substitutions,ingredients,product_ingredient_dependencies,ingredient_availability,product_availability TO restaurant_os_app;
  GRANT SELECT,INSERT ON menu_publications TO restaurant_os_app;
  REVOKE DELETE ON menus,menu_categories,menu_products,product_configurations,component_groups,component_options,option_substitutions,ingredients,product_ingredient_dependencies,ingredient_availability,product_availability,menu_publications FROM restaurant_os_app;
  REVOKE UPDATE ON menu_publications FROM restaurant_os_app;
END IF; END $$;
